REDUCE_BLOCK: tl.constexpr = 8192


@triton.jit
def _partial_sum_sq_kernel(
    x_ptr,
    out_ptr,
    N,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < N
    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    x_fp32 = x.to(tl.float32)
    partial_sum = tl.sum(x_fp32 * x_fp32)
    tl.store(out_ptr + pid, partial_sum)


@triton.jit
def _reduce_kernel(
    partial_sums_ptr,
    inv_norm_ptr,
    num_partial,
    REDUCE_BLOCK: tl.constexpr,
):
    acc = tl.zeros([REDUCE_BLOCK], dtype=tl.float32)
    for start in range(0, num_partial, REDUCE_BLOCK):
        offsets = start + tl.arange(0, REDUCE_BLOCK)
        mask = offsets < num_partial
        vals = tl.load(partial_sums_ptr + offsets, mask=mask, other=0.0)
        acc += vals
    total = tl.sum(acc)
    inv_norm = tl.rsqrt(total)
    tl.store(inv_norm_ptr, inv_norm)


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 2048}, num_warps=8, num_stages=2),
    ],
    key=["N"],
)
@triton.jit
def _normalize_kernel(
    x_ptr,
    out_ptr,
    inv_norm_ptr,
    N,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    inv_norm = tl.load(inv_norm_ptr)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < N
    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    result = x.to(tl.float32) * inv_norm
    tl.store(out_ptr + offsets, result.to(tl.bfloat16), mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        original_shape = x.shape
        x_flat = x.contiguous().view(-1)
        N = x_flat.numel()

        num_blocks = triton.cdiv(N, 8192)
        partial_sums = torch.empty(num_blocks, device=x.device, dtype=torch.float32)

        _partial_sum_sq_kernel[(num_blocks,)](x_flat, partial_sums, N, BLOCK_SIZE=8192)

        inv_norm = torch.empty(1, device=x.device, dtype=torch.float32)
        _reduce_kernel[(1,)](
            partial_sums, inv_norm, num_blocks, REDUCE_BLOCK=REDUCE_BLOCK
        )

        output_flat = torch.empty_like(x_flat)
        grid_norm = lambda META: (triton.cdiv(N, META["BLOCK_SIZE"]),)
        _normalize_kernel[grid_norm](x_flat, output_flat, inv_norm, N)

        return output_flat.view(original_shape)


